582      public FValue forIf(If x) {
583          List<IfClause> clauses = x.getClauses();
584          for (IfClause ifclause : clauses) {
585              GeneratorClause cond = ifclause.getTestClause();
586              Expr testExpr;
587              if (cond.getBind().isEmpty()) testExpr = cond.getInit();
588              else testExpr = bug(ifclause, "Undesugared generalized if expression.");
589              FValue clauseVal = testExpr.accept(this);
590              if (clauseVal instanceof FBool) {
591                  if (((FBool) clauseVal).getBool()) {
592                      return ifclause.getBody().accept(this);
593                  }
594              } else {
595                  if (maybeType(clauseVal.type())) {
596                      if (((FTraitOrObject) clauseVal.type()).getName().equals("Just")) return ifclause.getBody().accept(
597                              this);
598                  } else {
599                      return error(ifclause, errorMsg("If clause did not return boolean, " + "but ", clauseVal));
600                  }
601              }
602          }
603          Option<Block> else_ = x.getElseClause();
604          if (else_.isSome()) {
605              return else_.unwrap().accept(this);
606          } else {
607              return FVoid.V;
608          }
609      }

